import {LESSONS, PARTS, BY_CHAR} from './data.mjs';
import {STORAGE_KEY, freshProgress, normalizeProgress, candidates, shuffle, isCorrect, recordResult, selectSession, stats, localDate} from './engine.mjs';

const app=document.querySelector('#app');
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress=freshProgress(),storageAvailable=true,glyphs={},screen='home',session=null,ticker=null,remaining=30,filter='all',detail=null,message='';
try{progress=normalizeProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'));}catch{storageAvailable=false;}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5C8 2 4 3 2 4v16c3-2 6-1 10 1m0-16c4-3 8-2 10-1v16c-3-2-6-1-10 1Zm0 0v16',repeat:'M20 7v5h-5M4 17v-5h5M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5',arrow:'M4 12h16m-6-6 6 6-6 6',star:'m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1L2.2 9.4l6.1-.9Z',sound:'m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',bulb:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 3H9Z',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',back:'M20 12H4m6-6-6 6 6 6',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',leaf:'M20 3C7 2 2 9 5 16s16 3 15-13ZM5 20 16 9',flask:'M9 3h6m-5 0v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10',lock:'M6 10h12v11H6Zm3 0V6a3 3 0 0 1 6 0v4'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;}
function robot(kind='large'){
  return `<svg class="robot ${kind}" viewBox="0 0 220 230" fill="none" aria-hidden="true"><ellipse cx="111" cy="218" rx="64" ry="9" fill="#273e4412"/><path d="m53 116-22 27m133-27 24 19" stroke="#29474a" stroke-width="12" stroke-linecap="round"/><circle cx="27" cy="148" r="13" fill="#f7bd54" stroke="#29474a" stroke-width="4"/><path d="M79 180v23m60-23v23" stroke="#29474a" stroke-width="12"/><path d="M67 207h25m35 0h25" stroke="#29474a" stroke-width="12" stroke-linecap="round"/><rect x="50" y="91" width="121" height="99" rx="24" fill="#f6ba4c" stroke="#29474a" stroke-width="4"/><path d="M57 114h107" stroke="#e59c30" stroke-width="3"/><rect x="81" y="130" width="58" height="41" rx="8" fill="#fff8df"/><path d="m94 148 9 8 20-18" stroke="#29474a" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M111 30V15" stroke="#29474a" stroke-width="4"/><circle cx="111" cy="12" r="7" fill="#ec7855"/><rect x="38" y="31" width="146" height="82" rx="25" fill="#fff6d9" stroke="#29474a" stroke-width="4"/><path d="M44 49h134" stroke="#f0dfb8" stroke-width="3"/><rect x="33" y="58" width="10" height="25" rx="5" fill="#83bcb0" stroke="#29474a" stroke-width="3"/><rect x="179" y="58" width="10" height="25" rx="5" fill="#83bcb0" stroke="#29474a" stroke-width="3"/><path d="M71 67v12m78-12v12" stroke="#29474a" stroke-width="7" stroke-linecap="round"/><path d="M99 87q12 10 24-1" stroke="#29474a" stroke-width="4" stroke-linecap="round"/><ellipse cx="61" cy="85" rx="9" ry="5" fill="#efb49b"/><ellipse cx="160" cy="85" rx="9" ry="5" fill="#efb49b"/><circle cx="65" cy="177" r="3" fill="#29474a"/><circle cx="156" cy="177" r="3" fill="#29474a"/></svg>`;
}
function glyph(char,{colored=true,cls='',animated=false}={}){
  const groups=glyphs[char];
  if(!groups)return `<span class="glyph-text ${cls}" aria-label="${escapeHTML(char)}">${escapeHTML(char)}</span>`;
  let index=0;
  return `<svg class="glyph ${cls} ${animated?'draw':''}" viewBox="0 0 109 109" role="img" aria-label="${escapeHTML(char)}" fill="none" stroke-width="4.2" stroke-linecap="round" stroke-linejoin="round">${groups.map((part,i)=>`<g stroke="${colored?(i===0?'#287d83':'#e78047'):'#29474a'}">${part.map(d=>`<path d="${d}" ${animated?`style="--i:${index++}"`:''}/>`).join('')}</g>`).join('')}</svg>`;
}
function announce(text){document.querySelector('#announcer').textContent=text;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progress));storageAvailable=true;}catch{storageAvailable=false;}}
function stopTimer(){clearInterval(ticker);ticker=null;}
function speak(text){
  if(!('speechSynthesis' in window)){announce('このブラウザーでは読み上げに対応していません。');return;}
  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.rate=.85;speechSynthesis.speak(u);
}
function chime(){
  if(!progress.settings.sound)return;
  try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C();[523,659,784].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;g.gain.setValueAtTime(0,ctx.currentTime+i*.09);g.gain.linearRampToValueAtTime(.06,ctx.currentTime+i*.09+.01);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.09+.25);o.start(ctx.currentTime+i*.09);o.stop(ctx.currentTime+i*.09+.3);});setTimeout(()=>ctx.close(),800);}catch{}
}
function go(next){stopTimer();if('speechSynthesis' in window)speechSynthesis.cancel();screen=next;detail=null;message='';render();window.scrollTo({top:0,behavior:'instant'});}
function sidebar(){return `<aside class="sidebar"><button class="brand" data-action="home" aria-label="カンジ工房 ホーム"><span class="brand-mark"><b>木</b><b>才</b></span><span>カンジ工房<small>KANJI KOBO</small></span></button><span class="side-label">きょうも、ひとつ発見しよう。</span><nav aria-label="メインメニュー"><button data-action="home" class="nav-item ${screen==='home'?'active':''}">${icon('home')}工房のホーム</button><button data-action="collection" class="nav-item ${screen==='collection'?'active':''}">${icon('book')}漢字ずかん<span class="nav-count">${stats(progress).collected}</span></button><button data-action="review" class="nav-item">${icon('repeat')}もういちど</button></nav><div class="side-note"><span class="side-note-icon">${icon('bulb')}</span><p>小さな「わかった！」が、<br>きみの力になる。</p><span>工房長 コボより</span></div><button class="adult-link" data-action="settings">${icon('settings')}設定・おうちの方へ</button><span class="version">小学4年生 / おためし12文字</span></aside>`;}
function topbar(){const st=stats(progress);return `<header class="topbar"><span class="greeting">${screen==='collection'?'きみだけの、発見のきろく。':'こんにちは、カンジはかせ！'}<span class="greeting-wave">✳</span></span><div class="top-actions"><span class="discovery-pill">${icon('star')}<strong>${st.collected}</strong><span>文字 発見</span></span><button class="sound-button ${progress.settings.sound?'on':''}" data-action="sound" aria-label="効果音 ${progress.settings.sound?'オン':'オフ'}">${icon('sound')}<span>${progress.settings.sound?'ON':'OFF'}</span></button><span class="avatar" aria-label="はかせのアイコン">${icon('flask')}</span></div></header>`;}
function shell(content){return `<div class="layout">${sidebar()}<div class="main-area">${topbar()}<main id="main" class="main-content" tabindex="-1">${content}</main><footer class="footer"><span>組み立てると、思い出せる。</span><span>カンジ工房 <i>✦</i></span></footer></div></div>`;}
function home(){
  const st=stats(progress),next=selectSession(progress),collected=LESSONS.filter(l=>progress.records[l.char]?.collected);
  return shell(`<section class="hero"><div class="hero-copy"><span class="eyebrow"><span></span> あそんで、ひらめく。漢字のラボ</span><h1>「わかった！」を、<br>組み立てよう。</h1><p>部品をえらんで、ぴたっと合体。<br>きみの頭の中に、漢字の引き出しをつくろう。</p><div class="hero-tags"><span>${icon('check')} 紙もえんぴつもいらない</span><span>${icon('clock')} 1回 約3〜5分</span></div></div><div class="hero-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-spark spark-one">✦</span><span class="art-spark spark-two">✧</span><span class="floating-part part-a">木<small>き</small></span><span class="floating-part part-b">才<small>さい</small></span><span class="art-plus">＋</span><div class="hero-kanji">${glyph('材')}<span>ひらめき、発見！</span></div>${robot()}<div class="speech-bubble">いっしょに、つくろう！</div><span class="art-dot dot-one"></span><span class="art-dot dot-two"></span></div></section>
  <section class="dashboard-row"><div class="mission-card"><div class="section-kicker">TODAY'S MISSION <span>3文字のミニぼうけん</span></div><div class="mission-body"><div><h2>${st.collected===0?'はじめての漢字クラフト':st.collected===12?'ひらめきを、もういちど':'今日の漢字クラフト'}</h2><p>組み立てて、覚えて、見ないでチャレンジ！</p><div class="mini-steps"><span><b>1</b> つくる</span><i>→</i><span><b>2</b> おぼえる</span><i>→</i><span><b>3</b> 思い出す</span></div></div><div class="mission-tiles" aria-label="今日の3文字">${next.map((l,i)=>`<span class="mission-tile tile-${i}">${l.char}</span>`).join('')}</div></div><button class="primary start-button" data-action="start">${icon('spark')} ${st.collected?'つづきから、はじめる':'つくってみる'} ${icon('arrow')}</button><span class="mission-footnote">まちがえても大丈夫。ヒントといっしょに進もう。</span></div><div class="progress-card"><div class="section-kicker">MY COLLECTION ${icon('book')}</div><h2>ひらめき、あつまってる。</h2><div class="collection-count"><strong>${st.collected}</strong><span>/ 12 文字</span><div class="stamp">${icon('star')}</div></div><div class="progress-track"><span style="width:${st.collected/12*100}%"></span></div><p>${st.collected===0?'最初のひと文字を、見つけにいこう。':`見本なしで組めた字 ${st.independent} 文字`}</p><button class="text-button" data-action="collection">ずかんをひらく ${icon('arrow')}</button></div></section>
  <section class="seeds"><div class="section-title"><div><span class="section-kicker">LITTLE DISCOVERIES</span><h2>おなじ部品。ひろがる漢字。</h2></div><span class="small-note">知っている形が、きっとある。</span></div><div class="family-grid"><button class="family-card wood-family" data-action="family" data-family="木のなかま"><span class="family-symbol">木</span><div><h3>木のなかま</h3><p>きへんを使って、なに作る？</p><span class="family-examples">材 <i>・</i> 松 <i>・</i> 梅</span></div><span class="round-arrow">${icon('arrow')}</span></button><button class="family-card water-family" data-action="family" data-family="水のなかま"><span class="family-symbol">氵</span><div><h3>水のなかま</h3><p>さんずいから、ひらめこう。</p><span class="family-examples">清 <i>・</i> 泣 <i>・</i> 浴</span></div><span class="round-arrow">${icon('arrow')}</span></button><button class="family-card person-family" data-action="family" data-family="人のなかま"><span class="family-symbol">亻</span><div><h3>人のなかま</h3><p>にんべんには、なかまがいる。</p><span class="family-examples">信 <i>・</i> 働 <i>・</i> 仲</span></div><span class="round-arrow">${icon('arrow')}</span></button></div></section>
  <section class="bottom-note"><span class="note-star">${icon('bulb')}</span><div><h3>${st.due?'思い出すと、もっと自分のものになる。':'ひとつの部品が、次のヒントになる。'}</h3><p>${st.due?`もういちど組んでみたい漢字が ${st.due} 文字あるよ。`:'今日は「木」、あしたは「氵」。小さな発見をつなげていこう。'}</p></div><button class="text-button" data-action="${st.due?'review':'collection'}">${st.due?'もういちど遊ぶ':'漢字を見てみる'} ${icon('arrow')}</button></section>${!storageAvailable?'<p class="storage-notice">このブラウザーでは記録を保存できません。今の画面ではそのまま遊べます。</p>':''}`);
}
function start(lessons=selectSession(progress)){
  stopTimer();session={lessons,index:0,phase:'build',order:[],answers:[],layout:lessons[0].layout,slots:[null,null],active:0,options:candidates(lessons[0]),correct:false,hint:0,mistakes:0,revealed:false};screen='session';detail=null;message='';render();window.scrollTo({top:0,behavior:'instant'});
}
function current(){return session.phase==='recall'?session.order[session.index]:session.lessons[session.index];}
function phaseHeader(){const phase=session.phase;return `<div class="session-header"><button class="back-button" data-action="home">${icon('back')} 工房にもどる</button><div class="phase-track" aria-label="学習の流れ"><span class="${phase==='build'?'current':'done'}"><b>${phase!=='build'?'✓':'1'}</b> つくる</span><i></i><span class="${phase==='memory'?'current':phase==='recall'?'done':''}"><b>${phase==='recall'?'✓':'2'}</b> おぼえる</span><i></i><span class="${phase==='recall'?'current':''}"><b>3</b> 思い出す</span></div><span class="session-number">${phase==='memory'?'ひとやすみ':`${session.index+1} / ${session.lessons.length} 文字`}</span></div>`;}
function sentence(lesson){return escapeHTML(lesson.sentence).replace(/［(.*?)］/g,'<span class="question-reading">$1</span>');}
function layoutButton(layout,label){return `<button class="layout-choice ${session.layout===layout?'selected':''}" data-action="layout" data-layout="${layout}" aria-pressed="${session.layout===layout}"><span class="layout-icon ${layout}"><i></i><i></i></span>${label}</button>`;}
function sessionPage(){
  if(session.phase==='memory')return memoryPage();
  const l=current(),recall=session.phase==='recall',s=session;
  return shell(`${phaseHeader()}<section class="lesson-intro"><span class="lesson-label">${recall?'見本なしで、チャレンジ！':`${l.family} / はじめは見ながらでOK`}</span><h1>${recall?'どんな部品だったかな？':'部品をえらんで、組み立てよう。'}</h1><p class="example-sentence">${sentence(l)} <button class="inline-sound" data-action="read-question" aria-label="問題を読み上げる">${icon('sound')}</button></p></section><section class="workshop ${s.correct?'is-correct':''}"><div class="workshop-top"><span class="workshop-label">${icon(recall?'bulb':'flask')}${recall?'思い出す作業台':'漢字の作業台'}</span><span class="workshop-sub">${s.correct?'ぴたっと、合体！':'部品をタップ → マスに入るよ'}</span></div><div class="workbench ${recall?'recall-bench':''}">${!recall?`<div class="reference"><span class="small-label">今日つくる漢字</span>${glyph(l.char)}<span class="reading-badge">${escapeHTML(l.wordReading)}</span><span class="reference-word">${l.word}</span></div><span class="bench-arrow">${icon('arrow')}</span>`:''}<div class="assembly-zone">${s.correct?`<div class="assembled">${glyph(l.char,{animated:true})}<span class="assembled-spark">✦</span></div>`:`<div class="assembly-board ${s.layout||'lr'} ${s.layout?'':'needs-layout'}">${s.slots.map((part,i)=>`<button class="slot ${s.active===i?'active':''} ${part?'filled':''}" data-action="slot" data-slot="${i}" aria-label="${s.layout==='tb'?(i===0?'上':'下'):(i===0?'左':'右')}の部品${part?` ${PARTS[part][0]}をもどす`:''}" ${s.layout?'':'disabled'}>${part?`<span>${PARTS[part][0]}</span>`:`<span class="slot-plus">＋</span><small>${s.layout==='tb'?(i===0?'上':'下'):(i===0?'左':'右')}</small>`}</button>`).join('')}</div>`}<div class="layout-choices" ${s.correct?'hidden':''}>${layoutButton('lr','左右')}${layoutButton('tb','上下')}</div></div></div>
  ${s.correct?`<div class="success-message"><span>${icon('check')}</span><h2>${s.revealed?'見本でたしかめられた！':recall?'思い出せた！':'できた！ ぴたっと合体。'}</h2><p>${l.mnemonic}</p><span class="success-note">${recall?(s.revealed?'つぎは、見ないで組んでみよう。':s.hint||s.mistakes?'ヒントも、思い出す力になるよ。':'見本なしで組み立てられたね。'):l.meaning}</span></div>`:`<div class="palette-area"><div class="palette-heading"><span>部品をえらぼう</span><button class="plain-button" data-action="clear">入れなおす</button></div><div class="part-palette">${s.options.map(id=>`<button class="part-button ${s.slots.includes(id)?'used':''}" data-action="part" data-part="${id}" draggable="true" ${s.slots.includes(id)||!s.layout?'disabled':''} aria-label="部品 ${PARTS[id][0]} ${PARTS[id][1]}"><span>${PARTS[id][0]}</span><small>${PARTS[id][1]}</small></button>`).join('')}</div></div>`}
  <div class="workshop-bottom">${!s.correct?`<div class="feedback ${message?'has-message':''}" role="status">${message||(!s.layout?'まずは、左右か上下かをえらぼう。':recall?'頭の中の漢字を、組み立ててみよう。':l.mnemonic)}</div><div class="lesson-actions">${recall?`<button class="hint-button" data-action="hint">${icon('bulb')} ${s.hint>=3?'見本をたしかめる':'ヒントをもらう'}</button>`:`<button class="hint-button" data-action="read-mnemonic">${icon('sound')} 覚え方をきく</button>`}<button class="primary" data-action="check" ${s.slots.some(p=>!p)||!s.layout?'disabled':''}>合体させる ${icon('spark')}</button></div>`:`<button class="primary next-button" data-action="next">${recall?(s.index===s.lessons.length-1?'発見のきろくを見る':'つぎのチャレンジへ'):(s.index===s.lessons.length-1?'まとめて覚えよう':'つぎの漢字をつくる')} ${icon('arrow')}</button>`}</div></section><div class="helper-line">${icon('bulb')}${recall?'忘れても大丈夫。ヒントは何度でも使えるよ。':'二つの部品が、ひとつの漢字になる。形の変化も見てみよう。'}</div>`);
}
function memoryPage(){return shell(`${phaseHeader()}<section class="lesson-intro"><span class="lesson-label">頭の中に、しまっておこう。</span><h1>部品と、ならび方を覚えよう。</h1><p>あとで見本をかくすよ。覚え方を、心の中でとなえてみよう。</p></section><section class="memory-workshop"><div class="memory-top"><span>${icon('bulb')} ひらめきタイム</span><button class="plain-button" data-action="timer-toggle">${progress.settings.timer?'タイマーを使わない':'タイマーを使う'}</button></div><div class="memory-cards">${session.lessons.map(l=>`<article class="memory-card">${glyph(l.char)}<h2>${l.word}<small>${l.wordReading}</small></h2><div class="part-recipe"><span>${PARTS[l.parts[0]][0]}</span><i>＋</i><span>${PARTS[l.parts[1]][0]}</span></div><p>${l.mnemonic}</p><button class="text-button" data-action="speak-char" data-char="${l.char}">${icon('sound')} 覚え方をきく</button></article>`).join('')}</div><div class="memory-bottom"><div class="timer-line">${progress.settings.timer?`<span class="timer-circle">${icon('clock')}</span><div><span id="timer-number" class="timer-number">${remaining}</span><span> 秒</span><p id="timer-message">自分のペースで。時間がきても大丈夫。</p></div><button class="plain-button" data-action="timer-extend">＋30秒</button>`:`<span class="timer-circle">${icon('leaf')}</span><p>じゅんびができたら、チャレンジへ。</p>`}</div><button class="primary" data-action="recall">かくして、チャレンジ ${icon('arrow')}</button></div></section>`);}
function startTimer(){stopTimer();if(screen!=='session'||session?.phase!=='memory'||!progress.settings.timer)return;ticker=setInterval(()=>{if(remaining>0)remaining--;const n=document.querySelector('#timer-number');if(n)n.textContent=remaining;if(remaining===0){stopTimer();const msg=document.querySelector('#timer-message');if(msg)msg.textContent='そろそろ、思い出してみよう！ 延長もできるよ。';announce('じゅんびができたらチャレンジへ進もう。');}},1000);}
function resetQuestion(){const l=current();session.layout=session.phase==='build'?l.layout:null;session.slots=[null,null];session.active=0;session.options=candidates(l);session.correct=false;session.hint=0;session.mistakes=0;session.revealed=false;message='';}
function putPart(id,slot=session.active){if(session.correct||!session.layout||session.slots.includes(id)||!session.options.includes(id))return;session.slots[slot]=id;session.active=session.slots.findIndex(p=>!p);if(session.active===-1)session.active=slot;message='';render();}
function complete(revealed=false){
  if(session.correct)return;
  const l=current();session.correct=true;session.revealed=revealed;message='';
  if(session.phase==='recall'){
    const result={char:l.char,hinted:session.hint>0,mistakes:session.mistakes,revealed};session.answers.push(result);
    progress=recordResult(progress,l.char,result);save();
  }
  chime();render();announce(revealed?'見本でたしかめられた！':'できた！ ぴたっと合体。');
  document.querySelector('[data-action="next"]')?.focus({preventScroll:true});
}
function resultsPage(){
  const independent=session.answers.filter(r=>!r.hinted&&!r.mistakes&&!r.revealed).length;
  return shell(`<section class="result-header"><span class="eyebrow">MISSION COMPLETE</span><div class="result-mascot">${robot('small')}<span class="result-star one">✦</span><span class="result-star two">✦</span></div><h1>今日のひらめき、発見！</h1><p>${session.lessons.length}文字、最後までチャレンジできたね。</p></section><section class="results-card"><div class="result-stats"><div><strong>${session.lessons.length}</strong><span>文字と出会った</span></div><div><strong>${independent}</strong><span>見本なしで組めた</span></div></div><div class="result-letters">${session.answers.map(r=>{const l=BY_CHAR[r.char];return `<article>${glyph(l.char)}<h2>${l.word}</h2><span class="result-status ${r.revealed?'review':r.hinted||r.mistakes?'assisted':'independent'}">${r.revealed?'見本でたしかめた':r.hinted||r.mistakes?'ヒントと組めた':'見本なしで組めた'}</span></article>`;}).join('')}</div><p class="result-note">${icon('bulb')} 別の日にも思い出すと、きみの引き出しが育つよ。</p><div class="result-actions"><button class="secondary" data-action="collection">${icon('book')} ずかんを見る</button><button class="primary" data-action="start">もう3文字、つくる ${icon('arrow')}</button></div><button class="text-button result-home" data-action="home">今日はここまで。工房にもどる</button></section>`);
}
function collectionPage(){
  const st=stats(progress);const shown=LESSONS.filter(l=>filter==='all'||filter==='collected'&&progress.records[l.char]?.collected||filter==='review'&&progress.records[l.char]?.collected&&(progress.records[l.char].lastResult!=='independent'||progress.records[l.char].due<=localDate())||filter===l.family);
  return shell(`<section class="collection-header"><div><span class="eyebrow">MY KANJI COLLECTION</span><h1>きみの、漢字ずかん。</h1><p>ひとつずつ、頭の中の引き出しに。</p></div><span class="collection-header-count"><strong>${st.collected}</strong> / 12 文字</span></section><div class="collection-filters" aria-label="図鑑のしぼりこみ">${[['all','すべて'],['collected','見つけた漢字'],['review','もういちど'],['木のなかま','木のなかま'],['水のなかま','水のなかま'],['人のなかま','人のなかま']].map(([value,label])=>`<button class="filter-chip ${filter===value?'selected':''}" data-action="filter" data-filter="${value}" aria-pressed="${filter===value}">${label}</button>`).join('')}</div><div class="kanji-grid">${shown.map(l=>{const r=progress.records[l.char];return `<button class="kanji-card ${r?.collected?'collected':''}" data-action="detail" data-char="${l.char}"><span class="kanji-card-top">${l.family}<span>${r?.collected?icon('star'):icon('spark')}</span></span>${glyph(l.char,{colored:!!r?.collected})}<strong>${l.word}<small>${l.wordReading}</small></strong><span class="kanji-card-status">${r?.independentDates.length>=2?'別の日にも組めた':r?.independent?'見本なしで組めた':r?.collected?'出会った漢字':'これからの発見'}</span></button>`;}).join('')}</div>${!shown.length?'<div class="empty-state">'+icon('book')+'<h2>ここから、あつめていこう。</h2><p>工房でチャレンジすると、きろくが増えるよ。</p><button class="primary" data-action="start">つくってみる '+icon('arrow')+'</button></div>':''}<p class="collection-note">${icon('bulb')} どの漢字からでも遊べるよ。気になる漢字をタップしてみよう。</p>${detail?detailDialog():''}`);
}
function detailDialog(){const l=BY_CHAR[detail],r=progress.records[l.char];return `<div class="modal-backdrop"><section class="detail-dialog" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><button class="modal-close" data-action="close-detail" aria-label="閉じる">${icon('close')}</button><span class="eyebrow">${l.family}</span>${glyph(l.char)}<h2 id="detail-title">${l.word}<small>${l.wordReading}</small></h2><p>${l.meaning}</p><div class="detail-recipe">${l.parts.map(id=>`<span>${PARTS[id][0]}<small>${PARTS[id][1]}</small></span>`).join('<i>＋</i>')}</div><p class="detail-mnemonic">${l.mnemonic}</p><div class="detail-record"><span>見本なしで組めた <b>${r?.independent||0} 回</b></span><span>別の日のチャレンジ <b>${r?.independentDates.length||0} 日</b></span></div><button class="primary" data-action="start-char" data-char="${l.char}">この漢字で遊ぶ ${icon('arrow')}</button></section></div>`;}
function settingsPage(){return shell(`<section class="settings-header"><span class="eyebrow">SETTINGS & GUIDE</span><h1>設定・おうちの方へ</h1><p>きみのペースで、楽しく続けよう。</p></section><div class="settings-grid"><section class="settings-card"><h2>遊び方の設定</h2><div class="setting-row"><div><h3>効果音</h3><p>合体したときの、小さなお祝い。</p></div><button class="toggle ${progress.settings.sound?'enabled':''}" data-action="sound" role="switch" aria-checked="${progress.settings.sound}" aria-label="効果音"><span></span></button></div><div class="setting-row"><div><h3>暗記タイマー</h3><p>30秒を目安に。延長もできます。</p></div><button class="toggle ${progress.settings.timer?'enabled':''}" data-action="timer-setting" role="switch" aria-checked="${progress.settings.timer}" aria-label="暗記タイマー"><span></span></button></div><div class="settings-storage"><h3>きろくの持ち運び</h3><p>記録はこのブラウザー内に保存されます。ほかの端末へ移す場合は、ファイルを書き出してください。</p><button class="secondary" data-action="export">${icon('download')} きろくを書き出す</button><label class="secondary import-label">きろくを読みこむ<input type="file" id="import-progress" accept="application/json,.json" class="sr-only"></label><p class="import-message" role="status">${escapeHTML(message)}</p></div></section><section class="settings-card parent-guide"><h2>この工房で練習できること</h2><p>漢字を部品に分け、名前と配置を覚えて、見本なしで組み直します。普段の学習は、紙や鉛筆なしで完結します。</p><p>ミチムラ式の「部品を言葉でとらえる」考え方と、さかもと式の「短く覚えて再確認する」流れを参考にした独自の試作です。両手法の公式教材ではありません。</p><h3>「組めた」と「書けた」は別の記録です</h3><p>候補から部品を選ぶ課題のため、正答しても、何も見ずに手書きできることを保証しません。必要に応じて、最後に紙で書けるか確認してください。紙のテストをしなくても、すべての機能で遊べます。</p><h3>ヒントを使っても大丈夫</h3><p>獲得した文字は減りません。「見本なし」「ヒントあり」「見本で確認」を分けて記録します。日を変えて組めた文字も図鑑で確認できます。</p><p>収録は小学4年生の12字。部品の説明は覚え方の補助で、字源の説明ではありません。部品自体の書き方が未習得の場合は、別途支援してください。</p><div class="credits"><h3>参考・字形の出典</h3><a href="https://kanji.cloud/studymethod/method-features/" target="_blank" rel="noopener noreferrer">ミチムラ式公式の説明 ↗</a><a href="https://manatera.com/kanji/" target="_blank" rel="noopener noreferrer">さかもと式公式の説明 ↗</a><a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener noreferrer">筆画：KanjiVG © Ulrich Apel ↗</a><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">字形データ CC BY-SA 3.0（部品分割・色変更）↗</a><a href="./ATTRIBUTION.txt" target="_blank" rel="noopener noreferrer">素材の出典とライセンス ↗</a></div></section></div>`);}
function render(){
  const oldFocus=document.activeElement?.dataset?{...document.activeElement.dataset}:null;
  app.innerHTML=screen==='home'?home():screen==='session'?sessionPage():screen==='results'?resultsPage():screen==='collection'?collectionPage():settingsPage();
  // ロゴが「材」の正解部品を示さないよう、セッション中も中立な印を使う。
  const mark=app.querySelector('.brand-mark');if(mark)mark.innerHTML='<b>＋</b><b>✦</b>';
  if(detail){document.querySelector('.detail-dialog')?.focus();}
  else if(oldFocus?.action){
    let next=[...app.querySelectorAll('[data-action]')].find(el=>Object.entries(oldFocus).every(([k,v])=>el.dataset[k]===v)&&!el.disabled);
    if(oldFocus.action==='part'&&!next){next=app.querySelector('[data-action="check"]:not([disabled])')||app.querySelector('[data-action="part"]:not([disabled])');}
    next?.focus({preventScroll:true});
  }
  if(screen==='session'&&session?.phase==='memory')startTimer();
}
app.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const action=button.dataset.action;
  if(action==='home'){go('home');return;}
  if(action==='collection'){filter='all';go('collection');return;}
  if(action==='settings'){go('settings');return;}
  if(action==='start'){start();return;}
  if(action==='review'){start(selectSession(progress,{review:true}));return;}
  if(action==='family'){filter=button.dataset.family;go('collection');return;}
  if(action==='sound'){progress.settings.sound=!progress.settings.sound;save();render();return;}
  if(action==='timer-setting'){progress.settings.timer=!progress.settings.timer;save();render();return;}
  if(action==='filter'){filter=button.dataset.filter;render();return;}
  if(action==='detail'){detail=button.dataset.char;render();return;}
  if(action==='close-detail'){const char=detail;detail=null;render();document.querySelector(`[data-action="detail"][data-char="${char}"]`)?.focus();return;}
  if(action==='start-char'){start([BY_CHAR[button.dataset.char]]);return;}
  if(action==='speak-char'){const l=BY_CHAR[button.dataset.char];speak(`${l.wordReading}。${l.mnemonic}`);return;}
  if(action==='export'){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`kanji-kobo-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return;}
  if(screen!=='session')return;
  const s=session,l=current();
  if(action==='read-question'){speak(`${l.sentence.replace(/[［］]/g,'')}。${l.meaning}`);return;}
  if(action==='read-mnemonic'){speak(l.mnemonic);return;}
  if(action==='part'){putPart(button.dataset.part);return;}
  if(action==='slot'){const i=Number(button.dataset.slot);s.slots[i]=null;s.active=i;message='';render();return;}
  if(action==='layout'){if(s.correct)return;s.layout=button.dataset.layout;s.slots=[null,null];s.active=0;message='';render();return;}
  if(action==='clear'){s.slots=[null,null];s.active=0;message='';render();return;}
  if(action==='check'){
    if(s.correct)return;
    if(isCorrect(l,s.layout,s.slots))complete();
    else{s.mistakes++;message=s.layout!==l.layout?'ならび方を、もういちど考えてみよう。':'おしい！ 部品や置く場所を、もういちど見てみよう。';render();announce(message);}return;
  }
  if(action==='hint'){
    if(s.hint>=3){s.layout=l.layout;s.slots=[...l.parts];complete(true);return;}
    s.hint++;message=s.hint===1?`ならび方は「${l.layout==='lr'?'左右':'上下'}」だよ。`:s.hint===2?`最初の部品は「${PARTS[l.parts[0]][1]}」だよ。`:l.mnemonic;render();announce(message);return;
  }
  if(action==='next'){
    if(!s.correct)return;
    if(s.index<s.lessons.length-1){s.index++;resetQuestion();render();}
    else if(s.phase==='build'){s.phase='memory';remaining=30;render();}
    else{progress.sessions++;save();go('results');}window.scrollTo({top:0,behavior:'instant'});return;
  }
  if(action==='recall'){stopTimer();s.phase='recall';s.index=0;s.order=shuffle(s.lessons);resetQuestion();render();window.scrollTo({top:0,behavior:'instant'});return;}
  if(action==='timer-toggle'){progress.settings.timer=!progress.settings.timer;save();render();return;}
  if(action==='timer-extend'){remaining+=30;render();return;}
});
app.addEventListener('dragstart',event=>{const part=event.target.closest('[data-part]');if(part&&!part.disabled)event.dataTransfer.setData('text/plain',part.dataset.part);});
app.addEventListener('dragover',event=>{if(event.target.closest('[data-slot]'))event.preventDefault();});
app.addEventListener('drop',event=>{const slot=event.target.closest('[data-slot]');if(!slot||slot.disabled)return;event.preventDefault();putPart(event.dataTransfer.getData('text/plain'),Number(slot.dataset.slot));});
app.addEventListener('change',async event=>{
  if(event.target.id!=='import-progress')return;
  const file=event.target.files[0];if(!file)return;
  try{if(file.size>200000)throw new Error('ファイルが大きすぎます。');const raw=JSON.parse(await file.text());if(raw?.version!==1||!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records))throw new Error('カンジ工房の記録ファイルを選んでください。');const imported=normalizeProgress(raw);progress=imported;save();message='きろくを読みこみました。';}catch(e){message=e instanceof SyntaxError?'JSONファイルを読み取れませんでした。':e.message;}render();
});
document.addEventListener('keydown',event=>{
  if(detail&&event.key==='Escape'){const char=detail;detail=null;render();document.querySelector(`[data-action="detail"][data-char="${char}"]`)?.focus();}
  if(detail&&event.key==='Tab'){const all=[...document.querySelectorAll('.detail-dialog button:not([disabled]), .detail-dialog a')];if(!all.length)return;const first=all[0],last=all.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('detail-dialog'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
});
try{const response=await fetch('./glyphs.json');if(!response.ok)throw new Error('字形データを読み込めません。');glyphs=await response.json();}catch{announce('字形データが読めなかったため、標準の文字で表示します。');}
render();
